<?php
declare(strict_types=1);
namespace App\Entity;
use Doctrine\ORM\Mapping as ORM; use Symfony\Component\Uid\Uuid;
#[ORM\Entity] #[ORM\Table(name:'feed_incident')] #[ORM\UniqueConstraint(name:'uniq_feed_incident_open',columns:['feed_id'])]
final class FeedIncident { #[ORM\Id] #[ORM\Column(type:'uuid')] private Uuid $id; #[ORM\OneToOne] #[ORM\JoinColumn(name:'feed_id',nullable:false,onDelete:'CASCADE')] private Feed $feed; #[ORM\Column(length:255)] private string $message; #[ORM\Column] private int $occurrences=1; #[ORM\Column(name:'first_occurred_at')] private \DateTimeImmutable $firstOccurredAt; #[ORM\Column(name:'last_occurred_at')] private \DateTimeImmutable $lastOccurredAt; #[ORM\Column(name:'acknowledged_at',nullable:true)] private ?\DateTimeImmutable $acknowledgedAt=null; public function __construct(Feed $feed,\Throwable $error){$this->id=Uuid::v7();$this->feed=$feed;$this->message=mb_substr($error->getMessage(),0,255);$this->firstOccurredAt=$this->lastOccurredAt=new \DateTimeImmutable();} public function report(\Throwable $e):void{$this->message=mb_substr($e->getMessage(),0,255);++$this->occurrences;$this->lastOccurredAt=new \DateTimeImmutable();$this->acknowledgedAt=null;} public function acknowledge():void{$this->acknowledgedAt=new \DateTimeImmutable();} public function getId():Uuid{return $this->id;} public function getFeed():Feed{return $this->feed;} public function getMessage():string{return $this->message;} public function getOccurrences():int{return $this->occurrences;} public function getFirstOccurredAt():\DateTimeImmutable{return $this->firstOccurredAt;} public function getLastOccurredAt():\DateTimeImmutable{return $this->lastOccurredAt;} public function getAcknowledgedAt():?\DateTimeImmutable{return $this->acknowledgedAt;} }
